	let additions = 0;
	let deletions = 0;
	for (const file of changed) {
		const diff = await getDiff(repoPath, file.path, ctx);
		files.push({
			path: diff.file.path,
			oldPath: diff.file.oldPath ?? file.oldPath,
			status: diff.file.status,
